// (tab5-themes.yaml), et la palette où leurs rôles se lisent.
static constexpr int kStylesFormes = 12;
static const Palette* const kPaletteStyle[] = {&UIColor, &UIHorloge, &UIBandeau, &UIColor, &UIColor, &UIColor, &UIColor, &UIColor, &UIColor, &UIColor, &UIColor, &UIColor};
static constexpr uint32_t Palette::* kRolesFormes[] = {&Palette::GLASS_HI, &Palette::GLASS_HI_PAGE, &Palette::GLASS_LO, &Palette::GLASS_LO_PAGE, &Palette::GLASS_RIM};
